-- Trusted server reads remain available after API role/school authorization.
-- API own-school/foreign-school DTO tests are parent-owned; service itself is
-- deliberately global. The SQL result is an eight-field hours projection.
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT is((SELECT allocated_hours FROM public.get_bucket_summary('10600000-0000-4000-8000-000000000021')),10::numeric,'trusted own-school hours summary capability preserved');
SELECT is((SELECT allocated_hours FROM public.get_bucket_summary('10600000-0000-4000-8000-000000000022')),20::numeric,'trusted authorized foreign-school/admin hours summary capability preserved');
SELECT is((SELECT array_agg(k ORDER BY k) FROM public.get_bucket_summary('10600000-0000-4000-8000-000000000021') s CROSS JOIN LATERAL jsonb_object_keys(to_jsonb(s)) k),ARRAY['allocated_hours','annex_hours','available_hours','consumed_hours','display_name','hour_type_key','is_fixed_allocation','reserved_hours'],'summary projection includes only approved operational hour fields');
SELECT is((SELECT count(*)::int FROM public.contratos WHERE id::text LIKE '10600000-%'),2,'trusted backend source access preserved');
SELECT lives_ok($q$UPDATE public.contratos SET descripcion_manual='Synthetic trusted update' WHERE id='10600000-0000-4000-8000-000000000021'$q$,'trusted backend contract operation preserved');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claims','{"role":"anon"}',true);
SELECT throws_ok($q$SELECT snapshot_nombre_representante,snapshot_rut_representante FROM public.contratos$q$,'42501',NULL,'anonymous legal snapshot SELECT denied');
SELECT throws_ok($q$INSERT INTO public.contratos(numero_contrato,fecha_contrato,cliente_id) VALUES('CT106-anon','2026-01-01','10600000-0000-4000-8000-000000000011')$q$,'42501',NULL,'anonymous contract insert denied');
SELECT throws_ok($q$UPDATE public.contratos SET descripcion_manual='Synthetic unauthorized'$q$,'42501',NULL,'anonymous contract update denied');
SELECT throws_ok($q$DELETE FROM public.contratos$q$,'42501',NULL,'anonymous contract delete denied');
RESET ROLE;
SELECT ok(NOT has_table_privilege('authenticated','public.contratos','TRUNCATE'),'authenticated cannot bypass contract RLS via truncate');
SELECT is((SELECT prosecdef FROM pg_proc WHERE oid='public.get_bucket_summary(uuid)'::regprocedure),false,'existing summary remains invoker-rights; no raw contract bypass introduced');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname='public' AND tablename='contratos' AND policyname='forced_password_change_guard' AND permissive='RESTRICTIVE'),1,'forced password guard preserved');
SELECT * FROM finish();
ROLLBACK;
